INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('iron-juggernaut-blazing', 1, 'Flaming Fists (2)', 'Flaming punch: 1D4x10 M.D. plus combustibles ignite and burn. Flamethrower-like gout: 1D6x10 M.D. plus combustibles ignite (counts as two attacks). Fire Balls: 4D6 M.D. per single fire ball, 1D4x10+4 M.D. per dual blast.', 1, 'Ranged attacks: 1,600 feet (488 m).', 'Equal to the number of attacks per melee round.', 'Unlimited.', '+6 to strike with punches; +4 to strike with ranged attacks.', NULL),
  ('iron-juggernaut-blazing', 2, 'Laser Beam Eyes', '3D6 M.D.', 1, '2,000 feet (610 m).', 'Equal to the number of attacks per melee round.', 'Unlimited.', '+4 to strike with ranged attacks.', NULL),
  ('iron-juggernaut-blazing', 3, 'Other Weapons: Spiked Shield, Steam Attack', NULL, 1, NULL, NULL, NULL, NULL, 'Named only; this book prints no statistics for it. The block is a summary of the Coalition Wars entry it cites.'),
  ('iron-juggernaut-blazing', 4, 'Magic Spells', 'By spell: Lantern Light, Fireblast, Fire Whip and all Fire Elemental spells levels 1-4.', 0, NULL, 'Two by spell per melee round, in place of the six physical attacks.', 'P.P.E.: 1D4x100+360.', NULL, 'Cast at 6th level proficiency.'),
  ('iron-juggernaut-earthwake', 1, 'Lava Bolts from the Fingers', '6D6 M.D. from one large bolt, or 4D6 M.D. from a volley of four small bolts fired from the fingers (1D6 M.D. each).', 1, '1,200 feet (366 m).', 'Each blast or volley counts as a single attack.', 'Unlimited.', NULL, NULL),
  ('iron-juggernaut-earthwake', 2, 'Forearm Spear Launchers (2)', '1D6 M.D. per individual spear, 3D6 for a volley of three fired simultaneously at the same target, 5D6 for a volley of six and 1D4x10+6 for a volley of nine.', 1, '1,200 feet (366 m).', 'Single shot or volleys of three, six or nine.', 'Unlimited. Spears are magically replenished at the beginning of each melee round.', NULL, NULL),
  ('iron-juggernaut-earthwake', 3, 'Other Weapons: Mini-Missile Launcher, Steam Attack', NULL, 1, NULL, NULL, NULL, NULL, 'Named only; this book prints no statistics for it. The block is a summary of the Coalition Wars entry it cites.'),
  ('iron-juggernaut-earthwake', 4, 'Magic Spells', 'By spell: Chameleon (6), Climb (3), Concealment (6), Detect Concealment (6), Fool''s Gold (10), Repel Animals (7), Dispel Magic Barriers (20), Locate (30), Stone to Flesh (30), Speed of the Snail (50), Purification (20), Water to Wine (40), and all Earth Elemental spells levels 1-3.', 0, NULL, 'Two by magic spell per melee round, in place of the physical attacks.', 'P.P.E.: 1D4x100+224.', NULL, 'Cast at 6th level proficiency.'),
  ('iron-juggernaut-fury', 1, 'Ion Cannons (2)', '6D6 M.D. per blast.', 1, '3,000 feet (914 m).', 'Equal to the number of attacks per melee round.', 'Unlimited.', '+3 to strike.', NULL),
  ('iron-juggernaut-fury', 2, 'Forearm Blades (2)', '7D6 M.D. (single blade; 2D6 M.D. plus normal punch damage) or 2D4x10 M.D. (simultaneous double blade strike).', 1, NULL, 'Equal to the number of attacks per melee round.', NULL, '+9 to strike.', NULL),
  ('iron-juggernaut-fury', 3, 'Other Weapons: Steam Attack', NULL, 1, NULL, NULL, NULL, NULL, 'Named only; this book prints no statistics for it. The block is a summary of the Coalition Wars entry it cites.'),
  ('iron-juggernaut-fury', 4, 'Magic Spells', 'By spell: Cleanse, Manipulate Objects, Throwing Stones, Shatter, Create Wood, Mystic Fulcrum, Light Target, all Earth Elemental spells levels 1-4 and all Air Elemental spells levels 1-2, plus the Air Elemental spells Energy Disruption, Energy Field, Electric Arc, Dissipate Gases, Call Lightning, Ball Lightning and Electric Field.', 0, NULL, 'Two by magic per melee round, in place of the six physical attacks.', 'P.P.E.: 1D6x100+600.', NULL, 'All at 6th level proficiency.'),
  ('iron-juggernaut-iron-dragonfly', 1, 'Scythe Hands (2)', 'Metal Blades: 1D4x10+4 M.D. Electrified Blades: 1D6x10 M.D. (supernatural P.S. included). Cross Blade Lightning Strike: 6D6 M.D. per bolt.', 1, '1,600 feet (488 m) for energy blast.', 'Equal to the number of attacks per melee round.', 'Unlimited.', '+7 to strike with punches and kicks; +3 to strike with energy blasts.', NULL),
  ('iron-juggernaut-iron-dragonfly', 2, 'Forearm Mini-Missile Launchers (2)', '1D4x10 (armor piercing) or 1D6x10 (plasma).', 1, 'One mile (1.6 km).', 'Single shot or volleys of two, four or six.', '18 per arm for 36 total.', NULL, NULL),
  ('iron-juggernaut-iron-dragonfly', 3, 'Other Weapons: Steam Attack', NULL, 1, NULL, NULL, NULL, NULL, 'Named only; this book prints no statistics for it. The block is a summary of the Coalition Wars entry it cites.'),
  ('iron-juggernaut-iron-dragonfly', 4, 'Magic Spells', 'By spell: Blinding Flash (1), Globe of Daylight (2), Energy Bolt (5), Thunderclap (4), Fingers of the Wind (5), Float in Air (5), Energy Disruption (12), Impervious to Energy (20), Wind Rush (20), Dispel Magic Barrier (20), Summon Fog (140). Air Elemental spells: Stop Wind (5), Change Wind Direction (6), Howling Wind (7), Call Lightning (10), Ball Lightning (15), Miasma (7), Dissipate Gases (15), Invisible Wall (30), Electrical Field (35), Darken Sky (25) and Atmosphere Manipulation (50).', 0, NULL, 'Two by magic per melee round, in place of the six physical attacks.', 'P.P.E.: 1D4x100+188.', NULL, 'No proficiency level is printed in this block.'),
  ('iron-juggernaut-sea-viper', 1, 'Blade Hands (2)', '4D6 M.D. for most attacks, 6D6 M.D. for spinning blade attack.', 1, NULL, NULL, NULL, '+10 to strike in the water; half that out of it.', NULL),
  ('iron-juggernaut-sea-viper', 2, 'Blade Feet (2)', '5D6 M.D.', 1, NULL, NULL, NULL, '+10 to strike in the water; half that out of it.', NULL),
  ('iron-juggernaut-sea-viper', 3, 'Magic Spells', 'By spell: Turn Dead (6), Negate Magic (30), Energy Bolt (5), Magic Net (7), Escape (8), Summon Fog (140), Summon Rain (200), Summon Storm (300), Cleanse (6), Orb of Cold (6), Wave of Frost (6), Frost Blade (15), Create Water (15) and all Water Elemental spells levels 1-3.', 0, NULL, 'Two by magic per melee round, in place of the physical attacks.', 'P.P.E.: 1D4x100+175.', NULL, 'Cast at sixth level proficiency. This block prints no Other Weapons line.'),
  ('iron-juggernaut-thundering', 1, 'Forearm Blades (2)', '6D6 M.D. for single strike, 1D4x10+4 M.D. for double strike.', 1, NULL, 'Equal to the number of attacks per melee round.', NULL, '+11 to strike.', NULL),
  ('iron-juggernaut-thundering', 2, 'Mini-Missile Launcher', '1D4x10 M.D. (armor piercing) or 1D6x10 M.D. (plasma).', 1, 'One mile (1.6 km).', 'One or two at a time.', 'Six total.', NULL, NULL),
  ('iron-juggernaut-thundering', 3, 'Other Weapons: Electrical Bolts from the Eyes, Forearm Laser', NULL, 1, NULL, NULL, NULL, '+3 to strike with energy weapons.', 'Named only; this book prints no statistics for it. The block is a summary of the Coalition Wars entry it cites.'),
  ('iron-juggernaut-thundering', 4, 'Magic Spells', 'By spell: Light Target, Wind Rush, Electric Arc, Wave of Frost, and all Air Elemental spells levels 1-4.', 0, NULL, 'Three by magic per melee round, in place of the nine physical attacks.', 'P.P.E.: 1D4x100+300.', NULL, 'Cast at 6th level proficiency.'),
  ('iron-juggernaut-warhawk', 1, 'Pole Arm', '4D6 M.D. (sickle blade) or 1D6x10 M.D. (lightning strike).', 1, '3,000 feet (914 m) for lightning strike. Hand to hand for sickle blade.', 'Equal to the number of attacks per melee round.', 'Unlimited.', '+4 to strike with energy blasts.', NULL),
  ('iron-juggernaut-warhawk', 2, 'Silver Sword Forearm Blades (2)', '6D6 M.D. each.', 1, NULL, NULL, NULL, NULL, NULL);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('iron-juggernaut-warhawk', 3, 'Other Weapons: Steam Attack', NULL, 1, NULL, NULL, NULL, NULL, 'Named only; this book prints no statistics for it. The block is a summary of the Coalition Wars entry it cites.'),
  ('iron-juggernaut-warhawk', 4, 'Magic Spells', 'By spell: Cloud of Smoke (2), Globe of Daylight (2), Thunderclap (4), Ignite Fire (6), Fuel Flame (5), Fire Bolt (7), Fire Ball (10), Energy Disruption (12), Impervious to Energy (20), Wind Rush (20), Magic Pigeon (20), Cleanse (6), Shatter (5), Lantern Light (1), Light Target (6), Manipulate Objects (2+), Chromatic Protection (10), Reflection (7), Featherlight (10), Implosion Neutralizer (12), Electric Arc (8), Fireblast (8), Wall of Wind (40), Shockwave (35).', 0, NULL, 'Two by magic per melee round, in place of the eight physical attacks.', 'P.P.E.: 1D4x100+155.', NULL, 'All spells are at 6th level proficiency.'),
  ('iron-juggernaut-wing-blade', 1, 'Mega-Damage Hand to Hand Combat', 'Wing Strike with the blunt edge of a blade: 1D6x10+25 S.D.C., or 4D6 M.D. from a full strength strike. Scythe Blade: 7D6+10 M.D.; Power Punch/Stab: 2D4x10+10 M.D. (counts as two melee attacks). Blade Strike from one Lower (leg) Appendage: 6D6 M.D.; Power Strike/Stab: 1D6x10+6 (counts as two melee attacks). Simultaneous Blade Strike: 1D6x10+6 M.D. (counts as two attacks). Tail Blade: 5D6 M.D. Small Leg Blades (near hip): 4D6 M.D. Small Spiked Legs (12): 2D6 M.D. each. Flying Body Block: 3D6 M.D. and a 01-80% likelihood of knocking any opponent its size or smaller off its feet (victim loses two melee actions and initiative).', 1, NULL, 'Ten physical attacks per melee round. The small spiked legs can stab in groups of 2, 4 or 6, but each leg strike counts as one melee action/attack.', NULL, '+10 to strike.', 'Inflicts double damage to creatures vulnerable to silver or magic. The small spiked legs stab and hold: once stabbed in they are not released to stab again. The block prints no separate weapon systems and no Other Weapons line.'),
  ('iron-juggernaut-wing-blade', 2, 'Magic Spells', 'By spell: Freeze Water (8), Sheet of Ice (15), Hail (20), Shards of Ice (15), Wall of Ice (20), Ten Foot Ball of Ice (30), Orb of Cold (6), Foul Water (6), Float on Water (4), Liquids to Water (10), Lantern Light (1), Globe of Daylight (2), Thunder Clap (2), and Northwind.', 0, NULL, 'Two by spell per melee round, in place of the ten physical attacks.', 'P.P.E.: 1D4x100+140.', NULL, 'All cast at 6th level spell strength. The predominantly Water Elemental spells are described in Rifts Conversion Book One and in the Book of Magic.'),
  ('iron-juggernaut-millipede', 1, 'Plasma Cannons (2)', '1D6x10 M.D. per single blast, 2D6x10 per dual blast.', 1, '4000 feet (1219 m).', NULL, 'Unlimited.', '+5 to strike with energy weapons.', 'No rate of fire is printed for this weapon.'),
  ('iron-juggernaut-millipede', 2, 'Forearm Lasers', '4D6 M.D.', 1, '2,000 feet (610 m).', 'Each blast counts as one melee attack.', 'Unlimited.', '+5 to strike with energy weapons.', NULL),
  ('iron-juggernaut-millipede', 3, 'Flame Thrower (1; mouth)', '1D4x10 M.D. per "bolt," or 5D6 M.D. from a stream of fire.', 1, 'Fire Bolt: 2,000 feet (610 m). Flaming Stream: 300 feet (91.5 m).', 'Each blast counts as one melee attack.', 'Unlimited.', NULL, NULL),
  ('iron-juggernaut-millipede', 4, 'Mini-Missiles (12; forearm)', '1D4x10 or 1D6x10 depending on the missile.', 1, 'One mile (1.6 km).', NULL, '36 total.', NULL, 'No rate of fire is printed.'),
  ('iron-juggernaut-millipede', 5, 'Other Weapons: Hand to Hand Punch Attacks and Steam Attack', '6D6 M.D. for a full strength punch.', 1, NULL, NULL, NULL, '+9 to strike with punches.', 'The steam attack is named only; no statistics are printed for it.'),
  ('iron-juggernaut-millipede', 6, 'Magic Spells', 'By spell: all first level Earth Elemental magic plus Dirt to Sand (6), Crumble Stone (10), Mend Stone (15), Dig (8), Wall of Stone (15), Animate Object (12), Hopping Stones (6), Quicksand (15), and Sand Storm (15).', 0, NULL, NULL, 'Available P.P.E.: 1D4x100+100.', NULL, 'At 6th level spell strength. Attacks per melee is printed as Twelve, with no by-spell count.'),
  ('at-c8000-wing-blade-cyborg', 1, 'Prehensile Tail (1)', 'Three pairs of launchable vibro-blades: the two smaller ones inflict 2D6 M.D., the large one 3D6 M.D. Fixed tip vibro-blade stab: 1D6 M.D. Tail strike (blunt): 6D6 S.D.C.; restrained attack does half damage.', 1, 'Tail reach is 12 feet (3.6 m); flying blades: 500 feet (152 m), limited to line of sight.', 'Total hand to hand melee actions; each strike by a flying blade counts as one of the character''s melee attacks/actions.', NULL, '-1 to strike for each blade that is in flight.', 'Primary purpose: anti-personnel. The blades launch like mini-missiles and are directed by remote control; if not destroyed (15 M.D.C. for small, 25 for large) they return and can be reattached. The tail also feels around narrow openings, grabs small objects, parries, entangles, and its tip hooks on to help in climbing.'),
  ('at-c8000-wing-blade-cyborg', 2, 'Concealed Mouth Particle Beam Gun (1)', '1D4x10 M.D. per blast.', 1, '1200 feet (365 m)', 'Equal to the total number of hand to hand attacks.', '24 per hour, but is patched into power supply so it regenerates.', NULL, 'Primary purpose: anti-armor and anti-cyborg.'),
  ('at-c8000-wing-blade-cyborg', 3, 'Grappling Spike (nose horn)', '1D4 M.D.', 1, '200 feet (61 m)', 'Equal to the total number of hand to hand attacks.', 'One', NULL, 'Primary purpose: climbing tool; anti-armor and anti-cyborg. The horn jabs, stabs and parries, or its tip is fired on a cable for climbing or snagging vehicles and bots; afterwards the spike is retracted or the line cut and the spike abandoned.'),
  ('at-c8000-wing-blade-cyborg', 4, 'Cheek Blades', '1D6 M.D.', 1, NULL, NULL, NULL, NULL, 'Used for parrying and slashing with the head.'),
  ('at-c8000-wing-blade-cyborg', 6, 'Concealed Weapon Compartments', NULL, 0, NULL, NULL, 'Two concealed compartments in each leg. One contains a vibro-blade dagger (or stun stick or laser rod) and a pair of stun/flash grenades; the other typically two extra E-clips and an RMK medical kit (for use on others).', NULL, 'The standard snoop. No damage is printed here; the contents are catalog items. The non-weapon feature list prints one concealed compartment in each leg.'),
  ('at-c8000-wing-blade-cyborg', 7, 'Hand to Hand Combat', 'Restrained Punch: 1D6+12 S.D.C. Full Strength Punch: 3D6+12 S.D.C. Power Punch: 1D4 M.D. (counts as 2 melee attacks). Head Butt: 2D6 S.D.C. Kick: 4D6+12 S.D.C. Jump Kick/Leap Attack: 2D4 M.D. (counts as 2 melee attacks). Judo Style Throw/Flip: 3D6 S.D.C. Full Speed Ram/Body Block: 1D4 M.D. (counts as 2 melee attacks).', 1, NULL, 'Attacks per melee equal the character''s hand to hand combat skill selection and experience, +2 additional attacks per melee (includes tail, neck and arm bonuses).', NULL, '+2 on initiative, +2 to parry, +1 to dodge, +2 to pull punch, +1 to roll with punch/fall/impact, and +2 to save vs horror factor; plus P.P. 22 bonus of +4 to strike, parry and dodge.', 'The cyborg''s physical strength is S.D.C. based except for the occasional special attack such as a power punch. Also see the vibro-blade tail mega-damage.'),
  ('at-c9000-tsunami-cyborg', 1, 'Striking Tail/Particle Beam Gun', 'Tail strike (blunt): 6D6 S.D.C.; restrained attacks do half damage. With the vibro-blade, the strike inflicts 2D4 M.D. Particle Beam: 5D6 M.D.', 1, 'Tail reach is 6 feet (3.6 m), as printed; Particle Beam Weapon: 1,000 feet (305 m).', 'Total hand to hand melee actions.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-personnel, assault. The tail is not flexible enough to grab things; a vibro-blade and a particle beam weapon are built into its tip.'),
  ('at-c9000-tsunami-cyborg', 2, 'Arm Mini-Gun/Vibro-Axe', 'Mini-Gun: a burst is 20 rounds and inflicts 1D4x10 M.D.; can only fire bursts. The vibro-axe inflicts 4D6 M.D.', 1, '2000 feet/610 m (mini-gun); hand to hand (vibro-axe)', 'Equal to the total number of hand to hand attacks.', 'Mini-Gun: 1000 rounds in canister; that''s fifty bursts.', NULL, 'Primary purpose: anti-armor and anti-cyborg. The right arm holds the mini-gun, firing explosive bullets, in place of a hand; the rest of the arm is the ammo canister, with the vibro-axe below the gun.'),
  ('at-c9000-tsunami-cyborg', 3, 'Mini-Missiles (2)', 'Varies with missile type.', 1, 'About one mile.', 'One at a time, or in volleys of two.', 'Two mini-missiles.', NULL, 'Primary purpose: anti-aircraft, anti-armor. Secondary purpose: defense. Mounted on the back, on top of the jet thruster system.'),
  ('at-c9000-tsunami-cyborg', 4, 'Laser Eyes', 'Single beam does 2D6 M.D.; simultaneous double beam blast inflicts 4D6 M.D.', 1, '1000 feet (305 m).', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-cyborg. Secondary purpose: defense. The two beams always fire together unless the head has taken more than 20 M.D.C. of damage, which disables one eye laser; 40 M.D.C. or more disables both.'),
  ('at-c9000-tsunami-cyborg', 5, 'Concealed Weapon Compartments', NULL, 0, NULL, NULL, 'Two concealed compartments in each leg. One contains a vibro-blade dagger (or stun stick or laser rod) and a pair of stun/flash grenades; the other typically two extra E-clips and an RMK medical kit (for use on others).', NULL, 'The standard Tsunami. No damage is printed here; the contents are catalog items. The non-weapon feature list prints one concealed compartment in each leg.'),
  ('at-c9000-tsunami-cyborg', 6, 'Hand to Hand Combat', 'Restrained Punch: 1D6+13 S.D.C. Full Strength Punch: 3D6+13 S.D.C. Power Punch: 1D4 M.D. (counts as 2 melee attacks). Head Butt: 2D6 S.D.C. Kick: 4D6+13 S.D.C. Jump Kick/Leap Attack: 2D4 M.D. (counts as 2 melee attacks). Judo Style Throw/Flip: 3D6 S.D.C. Full Speed Ram/Body Block: 1D4 M.D. (counts as 2 melee attacks).', 1, NULL, 'Attacks per melee equal the character''s hand to hand combat skill selection and experience, +1 additional attack per melee (includes tail bonuses).', NULL, '+2 on initiative, +2 to parry, +1 to dodge, +2 to pull punch, +1 to roll with punch/fall/impact, and +2 to save vs horror factor; plus P.P. 23 bonus of +4 to strike, parry and dodge.', 'The cyborg''s physical strength is S.D.C. based except for the occasional special attack such as a power punch. Also see the vibro-blade tail mega-damage.'),
  ('at-c10000-imperial-dragon-cyborg', 1, 'Triple-Barrelled Particle Beam Gun', '1D6x10+10 M.D. per triple blast; each individual gun does 4D6 M.D.', 1, '3000 feet (915 m).', 'Total hand to hand melee actions.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-armor, assault. The main gun.'),
  ('at-c10000-imperial-dragon-cyborg', 2, 'Mini-Missile Launchers (2)', 'Varies with missile type.', 1, 'About one mile.', 'One at a time, or in volleys of two, three or six.', 'Six total; three per launcher.', NULL, 'Primary purpose: anti-aircraft, anti-armor. Secondary purpose: defense. One launcher on each side.'),
  ('at-c10000-imperial-dragon-cyborg', 3, 'Double Laser Turrets (2)', 'Each double laser blast inflicts 4D6 M.D.; a simultaneous two-turret blast does 1D6x10 M.D. (counts as two melee attacks/actions).', 1, '4000 feet (1200 m)', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-personnel, anti-aircraft. Secondary purpose: defense. Two dual laser mini-turrets on the flanks that swivel to fire front, sides, rear and straight up.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('at-c10000-imperial-dragon-cyborg', 4, 'Head Lasers', 'Single beam does 2D6 M.D.; simultaneous triple beam blast inflicts 6D6 M.D.', 1, '1000 feet (305 m).', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-cyborg. Secondary purpose: defense. A row of three laser guns above the eyes; more than 5 points of damage to the head puts one gun out of commission, and 15 or more points of mega-damage destroys the system.'),
  ('at-c10000-imperial-dragon-cyborg', 5, 'Smoke Dispenser', 'Varies with gas type.', 0, 'Each gas release/attack covers a 30 foot (9 m) area; additional attacks add a similar amount to the air.', 'Equal to the total number of hand to hand attacks.', 'Four canisters, each with 10 releases/attacks; up to four different gases, one in each canister.', NULL, 'Primary purpose: chemical warfare. Secondary purpose: defense. Four tubes on the lower front torso; common loads are smoke, mace, tear gas, tranquilizer/sleep gas and fire-extinguishing foam, with the same effects as the chemical spray bionic system.'),
  ('at-c10000-imperial-dragon-cyborg', 6, 'Vibro-Claws/Vibro-Tail', 'Each attack inflicts 3D6 M.D. Tail strike (blunt): 6D6 S.D.C.; restrained attack does half damage.', 1, NULL, NULL, NULL, NULL, 'The forelegs, hind legs and the end of the tail are all tipped with vibro-blades. The tail can feel around narrow openings, grab small objects, slash, parry or entangle.'),
  ('at-c10000-imperial-dragon-cyborg', 7, 'Hand to Hand Combat', 'Restrained Punch: 1D6+15 S.D.C. Full Strength Punch: 3D6+15 S.D.C. Power Punch: 1D4 M.D. (counts as 2 melee attacks). Head Butt: 2D6 S.D.C. Kick: 4D6+15 S.D.C. Jump Kick/Leap Attack: 2D4 M.D. (counts as 2 melee attacks). Judo Style Throw/Flip: 3D6 S.D.C. Full Speed Ram/Body Block: 1D4 M.D. (counts as 2 melee attacks).', 1, NULL, 'Attacks per melee equal the character''s hand to hand combat skill selection and experience, +1 additional attack per melee (includes tail bonuses).', NULL, '+1 on initiative, +1 to parry, +2 to dodge, +2 to pull punch, and +2 to save vs horror factor; plus P.P. 23 bonus of +4 to strike, parry and dodge (printed as P.P. 23 although the body is P.P. 22).', 'The cyborg''s physical strength is S.D.C. based except for the occasional special attack such as a power punch. Also see the vibro-blade tail mega-damage.'),
  ('at-c12000-flame-cloud-cyborg', 1, 'Flame Breath Plasma System', '1D6x10 M.D. per flame blast. The flame also starts fires if used against anything flammable.', 1, '2000 feet (610 m).', 'Total hand to hand melee actions.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-armor, assault. A plasma projector in the head breathes jets of plasma from the mouth; used mostly to strafe ground targets.'),
  ('at-c12000-flame-cloud-cyborg', 2, 'Laser Guns (2)', '4D6 M.D. per blast.', 1, '4000 feet (1200 m)', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-aircraft, anti-armor. Secondary purpose: defense. Mounted on the jet thrusters, firing from ports on the sides of the exhaust system.'),
  ('at-c12000-flame-cloud-cyborg', 3, 'Tail Double Particle Beam Cannon', 'Each double particle beam blast inflicts 1D4x10+10 M.D. A single blast does 4D6 M.D.', 1, '4000 feet (1200 m)', 'Equal to the total number of hand to hand attacks.', 'Effectively unlimited.', NULL, 'Primary purpose: anti-armor, anti-aircraft. Secondary purpose: defense. Two beam cannon on the tail that rotate to aim in any direction.'),
  ('at-c12000-flame-cloud-cyborg', 4, 'Vibro-Claws/Vibro-Tail', 'Each attack inflicts 3D6 M.D. Tail strike (blunt): 6D6 S.D.C.; restrained attacks do half damage.', 1, NULL, NULL, NULL, NULL, 'The forelegs, hind legs and the end of the tail are all tipped with vibro-blades. The tail can feel around narrow openings, grab small objects, slash, parry or entangle.'),
  ('at-c12000-flame-cloud-cyborg', 5, 'Hand to Hand Combat', 'Restrained Punch: 1D6+13 S.D.C. Full Strength Punch: 3D6+13 S.D.C. Power Punch: 1D4 M.D. (counts as 2 melee attacks). Head Butt: 2D6 S.D.C. Kick: 4D6+13 S.D.C. Jump Kick/Leap Attack: 2D4 M.D. (counts as 2 melee attacks). Judo Style Throw/Flip: 3D6 S.D.C. Full Speed Ram/Body Block: 1D4 M.D. (counts as 2 melee attacks).', 1, NULL, 'Attacks per melee equal the character''s hand to hand combat skill selection and experience, +1 additional attack per melee (includes tail bonuses).', NULL, '+1 on initiative (+2 to initiative in the air), +1 to parry, +1 to dodge, +2 to dodge in the air (if flying at below cruise speed), +2 to pull punch, and +2 to save vs horror factor; plus P.P. 23 bonus of +4 to strike, parry and dodge (printed as P.P. 23 although the body is P.P. 22).', 'The cyborg''s physical strength is S.D.C. based except for the occasional special attack such as a power punch. Also see the vibro-blade tail mega-damage.'),
  ('db-800-demon-eater-cyborg', 1, 'Concealed Forearm Particle Beam Weapons (2)', '5D6 M.D. per single blast, 1D6x10 M.D. if both arms are pointed at the same target.', 1, '300 feet (91.5 m).', 'Each individual blast counts as one melee attack; a dual blast counts as two rapid succession melee attacks, though an opponent dodges it as one.', 'Effectively unlimited, tied to the ''Borg''s power supply.', NULL, 'Above the wrists of both forearms; point and shoot. A heavy close combat weapon.'),
  ('db-800-demon-eater-cyborg', 2, 'Concealed Laser Eyes (2)', '2D6 M.D. per single blast, 4D6 M.D. if both eyes fire simultaneously at the same target.', 1, '1000 feet (305 m).', 'Each individual or simultaneous dual blast counts as one melee attack.', 'Effectively unlimited, tied to the ''Borg''s power supply.', NULL, 'Located under the eyes.'),
  ('db-800-demon-eater-cyborg', 3, 'Dual Prehensile Tails (2)', 'Blunt Tail Strike: 1D8 M.D. Blade Strike: 2D6+2 (printed without a unit, under the Mega-Damage heading).', 1, 'Reach: 12 feet (3.6 m).', 'Each tail strike counts as one melee attack/action.', NULL, 'Adds two attacks per melee round, +1 to strike, +2 to parry, +2 to disarm, +5 to entangle.', 'For climbing, scaling walls, swinging and close combat. Each tail ends in a curved blade that stabs, cuts and slashes and can be driven into rock and concrete for climbing.'),
  ('db-800-demon-eater-cyborg', 4, 'Prehensile Tongue (1)', '5D6 S.D.C. or 1D6x10 S.D.C. on a power punch/strike.', 0, 'Extends up to two and a half feet (0.76 m).', NULL, NULL, NULL, 'Added for dramatic effect as much as anything; strikes or stabs in close combat.'),
  ('db-800-demon-eater-cyborg', 5, 'Bionic Jaws & Teeth', '1D4 M.D. from a nip, 2D6 M.D. from a bite.', 1, NULL, NULL, NULL, NULL, 'For close combat with demons and other supernatural predators that bite and claw.'),
  ('db-800-demon-eater-cyborg', 9, 'Bionic Strength & Damage', '2D6+13 S.D.C. damage, or 2D4 M.D. with a power punch or kick (counts as two melee attacks).', 1, NULL, NULL, NULL, NULL, 'Bionic P.S. of 35. Printed in the statistical data, not in the numbered list; the ordinal follows the list''s last number.'),
  ('ab-830-assault-geo-borg', 1, 'Concealed Forearm Laser Beam Weapons (2)', '2D6 M.D. per single blast, 4D6 M.D. if both arms are pointed at the same target.', 1, '2000 feet (610 m).', 'Each individual blast counts as one melee attack; a dual blast counts as two rapid succession melee attacks, though an opponent dodges it as one.', 'Effectively unlimited, tied to the ''Borg''s power supply.', NULL, 'Above the wrists of both forearms; point and shoot. A multipurpose weapon for long range and close combat.'),
  ('ab-830-assault-geo-borg', 2, 'Concealed Compartments (2): Exploding Throwing Irons', '1D4 M.D. as a Vibro-Blade weapon only, +4D6 M.D. explosive damage.', 1, '300 feet (91.5 m).', 'Each throw of one or two blades counts as one melee attack.', 'Three in each leg, plus an additional 6-12 usually carried hooked inside the long vest. The compartments are printed as located in the hips.', NULL, 'Each hip compartment holds three crescent shaped throwing irons, set to explode on contact, after a three second delay, or on a detonation signal from the transmitter on the left wrist.'),
  ('ab-830-assault-geo-borg', 5, 'Bionic Strength & Damage', '2D6+8 S.D.C. damage, or 1D4 M.D. with a power punch or kick (counts as two melee attacks).', 1, NULL, NULL, NULL, NULL, 'Bionic P.S. of 30. Printed in the statistical data, not in the numbered list; the ordinal follows the list''s last number.'),
  ('ab-955-lion-geo-borg', 1, 'Concealed Forehead Lasers (2)', '2D6 M.D. per single blast, 4D6 M.D. if both are fired simultaneously at the same target.', 1, '1000 feet (305 m).', 'Each individual or dual blast counts as one melee attack.', 'Effectively unlimited, tied to the ''Borg''s power supply.', NULL, 'The pair of small gem-like items in the forehead between the eyes.'),
  ('ab-955-lion-geo-borg', 2, 'Concealed Pair of Extendible Arms (2)', NULL, 0, 'Reach: 3.5 feet (0.1 m), as printed.', NULL, NULL, NULL, 'Not a weapon in itself: a pair of light mechanical arms that extend from the chest to manipulate machines, use weapons and even drive a car (at a -25% skill penalty). Arm stats: P.S. 10, P.P. 10. They can hold any light Geofront weapon or tool, limited by weight and size.'),
  ('ab-955-lion-geo-borg', 5, 'Bionic Strength & Damage', '2D6+22 S.D.C. damage from a blunt pawing strike, 3D4 M.D. with a blunt power punch (counts as two attacks), 3D6+3 M.D. for Vibro-Claw strike kick, 3D6 M.D. from bite attack.', 1, NULL, NULL, NULL, NULL, 'Bionic P.S. of 44. Printed in the statistical data, not in the numbered list; the ordinal follows the list''s last number.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 16 juggernauts and bodies are in' AS assertion, count(*) AS got, 16 AS want
  FROM vehicles WHERE slug IN ('iron-juggernaut-blazing', 'iron-juggernaut-earthwake', 'iron-juggernaut-fury', 'iron-juggernaut-iron-dragonfly', 'iron-juggernaut-sea-viper', 'iron-juggernaut-thundering', 'iron-juggernaut-warhawk', 'iron-juggernaut-wing-blade', 'iron-juggernaut-millipede', 'at-c8000-wing-blade-cyborg', 'at-c9000-tsunami-cyborg', 'at-c10000-imperial-dragon-cyborg', 'at-c12000-flame-cloud-cyborg', 'db-800-demon-eater-cyborg', 'ab-830-assault-geo-borg', 'ab-955-lion-geo-borg');
SELECT 'their 79 locations are in' AS assertion, count(*) AS got, 79 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('iron-juggernaut-blazing', 'iron-juggernaut-earthwake', 'iron-juggernaut-fury', 'iron-juggernaut-iron-dragonfly', 'iron-juggernaut-sea-viper', 'iron-juggernaut-thundering', 'iron-juggernaut-warhawk', 'iron-juggernaut-wing-blade', 'iron-juggernaut-millipede', 'at-c8000-wing-blade-cyborg', 'at-c9000-tsunami-cyborg', 'at-c10000-imperial-dragon-cyborg', 'at-c12000-flame-cloud-cyborg', 'db-800-demon-eater-cyborg', 'ab-830-assault-geo-borg', 'ab-955-lion-geo-borg');
SELECT 'their 71 weapon entries are in' AS assertion, count(*) AS got, 71 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('iron-juggernaut-blazing', 'iron-juggernaut-earthwake', 'iron-juggernaut-fury', 'iron-juggernaut-iron-dragonfly', 'iron-juggernaut-sea-viper', 'iron-juggernaut-thundering', 'iron-juggernaut-warhawk', 'iron-juggernaut-wing-blade', 'iron-juggernaut-millipede', 'at-c8000-wing-blade-cyborg', 'at-c9000-tsunami-cyborg', 'at-c10000-imperial-dragon-cyborg', 'at-c12000-flame-cloud-cyborg', 'db-800-demon-eater-cyborg', 'ab-830-assault-geo-borg', 'ab-955-lion-geo-borg');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('iron-juggernaut-blazing', 'iron-juggernaut-earthwake', 'iron-juggernaut-fury', 'iron-juggernaut-iron-dragonfly', 'iron-juggernaut-sea-viper', 'iron-juggernaut-thundering', 'iron-juggernaut-warhawk', 'iron-juggernaut-wing-blade', 'iron-juggernaut-millipede', 'at-c8000-wing-blade-cyborg', 'at-c9000-tsunami-cyborg', 'at-c10000-imperial-dragon-cyborg', 'at-c12000-flame-cloud-cyborg', 'db-800-demon-eater-cyborg', 'ab-830-assault-geo-borg', 'ab-955-lion-geo-borg') AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~085-iron-juggernauts-and-cyborg-bodies.sql');
